package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
/** Same receipt/queue locks and idempotent mutations as the Web. No implicit resubmission. */
final class QueuedConversationDialog {
 static void show(MainActivity owner,Runnable recovery){try{JSONArray rows=ConversationContinuation.ledger(owner);LinearLayout box=new LinearLayout(owner);box.setOrientation(1);TextView info=new TextView(owner);info.setText("スマホ・Web共通の会話テキストです。受理前だけ編集・取消できます。画像添付・生成処理は対象外です。");box.addView(info);Button restore=new Button(owner);restore.setText("送信控えを開く");restore.setOnClickListener(v->recovery.run());box.addView(restore);Button refresh=new Button(owner);refresh.setText("送信状況を更新");box.addView(refresh);JSONObject runtime=owner.webConversationRuntime();int count=0;for(int i=rows.length()-1;i>=0&&count<30;i--){JSONObject row=rows.getJSONObject(i);if(!row.optBoolean("tracked"))continue;count++;Button b=new Button(owner);b.setText(row.optString("requestState")+" / "+row.optString("message").substring(0,Math.min(70,row.optString("message").length())));box.addView(b);b.setOnClickListener(v->detail(owner,row,rows,runtime,info));}if(count==0)info.setText("対象の送信記録はまだありません。送信控えから内容を確認できます。");ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("送信待ち・待ち時間").setView(scroll).setPositiveButton("閉じる",null).create();refresh.setOnClickListener(v->{dialog.dismiss();show(owner,recovery);});dialog.show();}catch(Exception e){new AlertDialog.Builder(owner).setMessage("送信状況を取得できません。再送や取消はしていません。").setPositiveButton("閉じる",null).show();}}
 private static void detail(MainActivity owner,JSONObject row,JSONArray rows,JSONObject runtime,TextView status){AlertDialog.Builder builder=new AlertDialog.Builder(owner).setTitle("選んだ質問の状態").setMessage(row.optString("message")+"\n\n"+ConversationWait.reason(row,rows,runtime,0)+"\n受理と操作が競合した場合は保存を拒否します。元の処理を続けます。").setNegativeButton("閉じる",null);if(row.optString("requestState").equals("QUEUED")){builder.setPositiveButton("本文を編集",(d,w)->edit(owner,row,status));builder.setNeutralButton("送信前に取消",(d,w)->new AlertDialog.Builder(owner).setMessage("この質問を、メガネ受理前の場合だけ取り消しますか？").setPositiveButton("取り消す",(a,b)->change(owner,row,"cancel","",java.util.UUID.randomUUID().toString(),status,null)).setNegativeButton("戻る",null).show());}builder.show();}
 private static void edit(MainActivity owner,JSONObject row,TextView status){EditText input=new EditText(owner);input.setText(row.optString("message"));input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2400)});String changeId=java.util.UUID.randomUUID().toString();AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("受理前の質問を差し替える").setMessage("元の依頼を編集済みにして、新しいIDの依頼へ差し替えます。受理済みなら拒否します。").setView(input).setPositiveButton("編集して送信待ちへ",null).setNegativeButton("戻る",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(input.getText().toString().trim().isEmpty()){input.setError("本文を入力してください");return;}dialog.getButton(-1).setEnabled(false);change(owner,row,"edit",input.getText().toString(),changeId,status,dialog);}));dialog.show();}
 private static void change(MainActivity owner,JSONObject row,String action,String text,String changeId,TextView status,AlertDialog dialog){new Thread(()->{try{JSONObject data=new JSONObject().put("key",row.getString("key")).put("action",action).put("changeId",changeId);if(action.equals("edit"))data.put("message",text);QueuedConversation.change(owner,data);owner.runOnUiThread(()->{if(owner.isDestroyed())return;status.setText(action.equals("edit")?"編集後の質問へ差し替えました。状況を更新してください。":"送信前に取り消しました。状況を更新してください。");if(dialog!=null)dialog.dismiss();});}catch(Exception e){owner.runOnUiThread(()->{if(owner.isDestroyed())return;status.setText("操作を確認できません："+e.getMessage()+"。状態を更新し、再送する前に確認してください。");if(dialog!=null&&dialog.isShowing())dialog.getButton(-1).setEnabled(true);});}},"NativeQueuedConversationChange").start();}
 private QueuedConversationDialog(){}
}
